        )
        log = self._read_log()
        log["events"][2]["details"] = {"source": "s1"}
        self._write_log(log)
        self._expect_503_and_not_ready()

    def test_vote_for_unknown_operation(self):
        audit = AuditStore(self.tmpdir)
